const showSchema = new mongoose.Schema(
  {
    title: {
      type: String,
      required: [true, "title is required"],
      trim: true,
      maxlength: 120,
    },
    host: {
      type: String,
      required: [true, "host is required"],
      trim: true,
    },
    category: {
      type: String,
      enum: ["tech", "news", "comedy", "education"],
      default: "tech",
    },
  },
  { timestamps: true }
);

export default mongoose.model("Show", showSchema);
